=== FILE: tb/uart_tx_reload_while_busy_tb.v ===
// Directed reproduction for uart_tx: a start pulse while a frame is in flight
// must be ignored (per the design header). Frame 1 is a control frame with no
// interference; frame 2 receives a mid-frame start pulse with different data.
`timescale 1ns / 1ps
module uart_tx_reload_tb;
    localparam integer CPB = 8;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire       tx;
    wire       busy;

    integer    checks = 0;
    integer    fails  = 0;
    integer    k;
    reg  [7:0] rx_byte;
    reg        rx_stop;
    reg        idle_ok;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk  (clk),
        .rst  (rst),
        .start(start),
        .data (data),
        .tx   (tx),
        .busy (busy)
    );

    always #5 clk = ~clk;

    task check;
        input              cond;
        input [8*48-1:0]   name;
        begin
            checks = checks + 1;
            if (cond)
                $display("CHECK PASS: %0s", name);
            else begin
                fails = fails + 1;
                $display("CHECK FAIL: %0s", name);
            end
        end
    endtask

    // Wait for the transmitter to be idle, then issue a one-cycle start pulse.
    task send_byte;
        input [7:0] d;
        begin
            @(negedge clk);
            while (busy) @(negedge clk);
            data  = d;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
        end
    endtask

    // Receive one 8N1 frame, sampling near the centre of each bit on falling edges.
    task recv_byte;
        output [7:0] b;
        output       s;
        integer      i;
        begin
            @(negedge tx);
            repeat (CPB / 2) @(negedge clk);
            if (tx !== 1'b0)
                $display("NOTE: start bit not low at its centre (t=%0t)", $time);
            for (i = 0; i < 8; i = i + 1) begin
                repeat (CPB) @(negedge clk);
                b[i] = tx;
            end
            repeat (CPB) @(negedge clk);
            s = tx;
        end
    endtask

    initial begin
        #200000;
        $display("TIMEOUT: simulation did not complete");
        $display("TEST FAILED");
        $finish;
    end

    initial begin
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (4) @(negedge clk);

        // Frame 1: control, no interference.
        fork
            send_byte(8'hA5);
            recv_byte(rx_byte, rx_stop);
        join
        $display("frame 1: sent 0xa5, received 0x%h, stop=%b", rx_byte, rx_stop);
        check((rx_byte === 8'hA5) && (rx_stop === 1'b1), "frame 1 data and stop (control)");

        repeat (2 * CPB) @(negedge clk);

        // Frame 2: start pulse with different data during data bit 2.
        fork
            begin
                send_byte(8'h5A);
                repeat (3 * CPB) @(negedge clk);
                if (busy !== 1'b1)
                    $display("NOTE: busy not high when mid-frame pulse issued (t=%0t)", $time);
                data  = 8'h0F;
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
                data  = 8'h00;
            end
            recv_byte(rx_byte, rx_stop);
        join
        $display("frame 2: sent 0x5a (pulse with 0x0f mid-frame), received 0x%h, stop=%b",
                 rx_byte, rx_stop);
        check(rx_byte === 8'h5A, "frame 2 data unaffected by start while busy");
        check(rx_stop === 1'b1,  "frame 2 stop bit");

        // The ignored pulse must not launch another frame.
        idle_ok = 1'b1;
        for (k = 0; k < 4 * CPB; k = k + 1) begin
            @(negedge clk);
            if (tx !== 1'b1) idle_ok = 1'b0;
        end
        check(idle_ok, "line idle after frame 2");

        $display("RESULT: %0d of %0d checks failed", fails, checks);
        if (fails != 0)
            $display("TEST FAILED");
        else
            $display("TEST PASSED");
        $finish;
    end
endmodule
=== END FILE ===

